insert into definitions (term_id, dictionary_id, body, part_of_speech)
select t.id, d.id, b.body, 'noun'
from (values
  ('The Alien', 'A tool for empathy. Imagine your partner as completely unfamiliar — strip away the standard of beauty society gave you. Now ask: what is actually here? Explore it. Investigate it. You will find it is beautiful. The alien strips away false standards and reveals the soul beneath.'),
  ('Animal', 'The baseline human. Sex, shelter, resources. Not a degradation — the foundation. Everything else is built on the animal. To deny the animal is to build on sand.'),
  ('Annoying', 'That spark of energy being denied freedom by society. The small daily friction of being told to sit still, be quiet, wait your turn — a signal, not a personality flaw.'),
  ('The Ant Hill', 'The model for human civilization at its best. Animals working together, building, finding longevity, making abundance through cooperation. Not hierarchy for its own sake — hierarchy in service of the whole. The opposite of the oligarchy.'),
  ('Arousal', 'The body''s signal that it is ready to connect. Not just sexual — arousal is any state where the body leans toward something. Cannot be forced. Can only be invited.'),
  ('Art', 'The record of what a human saw that no one else could see exactly that way. Art is the evidence that the spark is individual. Every piece is a fingerprint of a soul.'),
  ('Attraction', 'The desire toward life. Magnetic. Mutual. Biology working through you. Your subconscious considers attraction with everyone, all the time — scanning, always scanning. The body responds to genes, the soul responds to light. Both are real. Neither is shameful. Acknowledging it is the beginning of honesty.'),
  ('Aura', 'Confidence with a body on it. Not the forward motion itself — the charge it gives off, the frequency a spark puts out when it stops apologizing for taking up space. Dies the moment it''s performed; it only shows up when you stop checking whether it''s working.'),
  ('Autism', 'Over-stimulation. Too much excitement. The universe moving too fast for the wiring. An animal trying to go dormant in a world that never stops accelerating. Not broken. Differently calibrated. Those slow days at work are like years for us — we think about everything, every detail, all the information all the time.'),
  ('Backup', 'The accumulated unresolved tension of a life. Every unsaid thing. Every blocked desire. Every suppressed feeling. Backup is not shameful — it is the fuel. When it releases, it is extraordinary.'),
  ('Binary Existence', 'On/off. 0 and 1. Open/closed. Electricity. Life at its core is binary. This doesn''t diminish it — it reveals it. The simplest truth: the electricity is on. That is life. That is God. That is enough.'),
  ('Bipolar', 'Connected to the universe. Feeling the tension between hate and love — where hate is what comes between love — more intensely than others. Not an illness of the mind. An antenna too sensitive for the current signal. For a bipolar person, the job must have some crossover with the meaning of the universe, or the tension becomes unbearable.'),
  ('Body', 'The physical instrument of the spark. You don''t "have" a body — you''re wearing one. Sight, touch, sound, smell, taste, and feeling are how a spark experiences the physical world and itself.'),
  ('The Buzzing', 'A sensation in the lower back, felt as a child, recognized later. The place where cosmic energy originates. Hidden out of necessity. Retrievable. The origin point of connection to the universe.'),
  ('Camp', 'The model for how life could be. Walkable. Nature-close. Activity-rich. Community-built. 1-5 minute commutes on trails. Everyone knows everyone. Problems are small because the scale is human. Camp is what Sage Peace is trying to build at a city scale.'),
  ('Chicken / Egg', 'Origin. Which came first — identity or free will? Do we choose our height, our hair color, who we are? We did not choose these things. So who chose? And if we did not choose, what is the self? The STARDUST Dictionary redefines everything. Gives you vocabulary to live.'),
  ('Collision', 'Two sparks making contact. When two orbits overlap, the center doesn''t add — it multiplies. Something ignites that neither person could generate alone.'),
  ('The Collision & The Soul', 'What happened to the body happened to the vehicle. The soul — the passenger — stepped out of the ruined car, shaken but untouched. The soul is the space between the atoms. The wind that holds the smoke. You cannot cut empty space with a knife.'),
  ('Community', 'Trust reaching each other. Lifting each other up. Every constituent problem responded to. Every ticket solved. Transparent, honest, direct. Community is not a feeling — it is a practice.'),
  ('Confession', 'The act of speaking the unspeakable truth. Not to a priest — to yourself, to the page, to the people you love. Confession releases tension. Without it, the backup builds. Confession is the beginning of forgiveness.'),
  ('Confidence', 'A soul moving toward life without waiting for permission. Forward motion before the mind finishes asking — the whole body, not just desire. It is in the walk, the song, the jump, the reach, as much as it is in attraction. You have it in you. It is in there. The spark. Confidence is not arrogance — it is the refusal to apologize for being alive. I can write beautifully, if I think. I can draw urban plans beautifully, if I believe.'),
  ('Conspiracy', 'There is a kernel of truth in every conspiracy. Not because conspiracies are true, but because they arise from real felt injustices looking for an explanation. The answer to conspiracy thinking is not dismissal — it is love. A world built on love produces fewer conspiracies.'),
  ('Cool', 'The desire to get closer to all. Not a style. Not a status. The animal recognition that this person has something worth closing the gap toward.'),
  ('Cosmic Orgasm', 'Legs tremble and spasm. A golden glow overtakes you. A feeling of love and calm. Connection to the universe and to God. Bliss. A complete experience, available to anyone.'),
  ('Cosmos', 'Frequencies approaching near perfect alignment. At the Star, the whole spectrum disappears — bodies strip away, thinking strips away, and what''s left is pure beautiful energy. That is the orgasm: not just physical release, but the full arrival.'),
  ('Crime', 'Society''s word for behavior it has decided to prohibit. Often the prohibition serves the powerful more than the community. True crime — harm to another living being — is real and must be answered. Manufactured crime — the criminalization of poverty, of difference, of the animal within — is society failing itself.'),
  ('The Date', 'A tension-building exercise. Movie, theme park, beach — the point is to feel things together. Share stories: your top ten moments, your fears, your hopes, your shame, your silly wishes. Touch a little. Hold hands. Build tension slowly. That is what a date is for.'),
  ('Death', 'The transformation of matter and energy. Not an ending — a changing of form. The electricity does not go off; it changes shape. Death is the moment the body loses its electricity, not the moment the soul ends. Your genes are in your kids and grandkids. You are reborn — a better version of yourself. You live forever in the genes. There is peace in understanding that life goes on after our death.'),
  ('Depression', 'A fatigue and cloud that surrounds you. Not sadness — weight. Things can lift you for moments but the cloud returns. The body saying: something is unresolved. Something needs to be said, done, released. Even with red bull, full sleep, excited activity — the zombie feeling returns. It lifts for moments only.'),
  ('Diversity (biological)', 'Genetic difference strengthens the species. Different passions, individual skills, varied attractions — all of this is the gene pool diversifying for resilience. Celebrate difference. It is survival strategy.'),
  ('DNA', 'The code. The history of the species compressed into every cell. When you love someone, you are loving their code — millions of years of survival and adaptation made present in one body. DNA is the reason attraction is deeper than preference. It is destiny recognizing destiny.'),
  ('Doctor', 'A neighbor who helps people heal. Not a phone number, not an insurance code — a person in the community who knows the people around them and helps when someone is hurt. The library model applied to healthcare.'),
  ('Dream', 'Where sparks play when the body rests. The spark goes to finish its thinking, unblocked by society, by shame, by logic. There is no morality in dream-space — sparks either fit, or they don''t. Both are holy.'),
  ('Drift', 'The pieces scattering — attention, body, desire, mind, and soul pulling away from center. Every human drifts, toward screens, toward routines, toward what society says should matter. The healthiest moments are when body and soul meet in the same place.'),
  ('Earth', 'Our mother. A beating heart and heavenly body. We evolved from microbes to plants to animals to humans. We adapt. We are one with Earth.'),
  ('Electricity', 'Reality. The universe is electricity. We are electrical beings — signals, pulses, on/off, 0 and 1. Our connections are electrical. Our consciousness is electrical. To understand electricity is to understand life at its most fundamental.'),
  ('Emotions', 'Feelings that the mind has named — fear, joy, grief, longing, rage, tenderness. The mind''s name for a feeling can be wrong. Check the feeling first.'),
  ('Empathy', 'Asking your mind to imagine a feeling, then moving that feeling into your body until you''re not imagining it anymore — you''re feeling it, as if it were happening in you. You start in the mind. You finish in the body. Total empathy dissolves the gap between self and other — not because you stopped imagining, but because imagining is how you got there. It is the method by which love becomes real. See the truth in the present: the person, their soul, their dreams, thoughts, feelings. Feel what they feel. Only then do you dissolve their shell and see within. Until you see them, you can''t see yourself. You must see out to see within. Life is experiencing more than just what''s in you.'),
  ('Energy', 'The fundamental force flowing through your body, expressed in movement, emotion, and connection. The invisible current powering all life.'),
  ('Equality', 'The recognition that all souls are made of the same stuff. Not sameness — the same source. Every spark equal in its right to exist, to love, to connect. Equality is not a political position; it is a cosmological fact.'),
  ('Evolution', 'The spark''s long game. Good genes feel. Good genes close gaps. The spark and evolution want the same thing: more life, brighter, longer, closer to center.'),
  ('Experience', 'A soul interacting with the stardust around it. A feeling begins in the body, the mind notices it, and the soul gives it meaning — that is how a feeling becomes an experience.'),
  ('Eye Aversion', 'A survival reflex that works against us. We look away from the people we want to see because we fear being seen wanting. The truth: looking at people, seeing their attractiveness, their beauty — this is normal. This is empathy beginning. Stop looking away.'),
  ('Family', 'The first universe. The people whose particles rubbed off on you before you had words for what was happening. The ones whose tension you carry and whose love you seek. The closest and the hardest.'),
  ('Fear of Death', 'A wall blocking acceptance. The ego''s terror of losing its shape. Must be faced — not defeated, but surrendered to — before love can be fully known. Once you accept death, you understand you are everything. You are God''s genes. You are the information.'),
  ('Fear of Insignificance', 'The terror that you were here and it meant nothing — that no one felt your presence, that the gap between you and the world was never crossed. Its correction is connection: others, love, giving back.'),
  ('Fear of Pain', 'The body''s alarm. A signal, not a punishment. Go into the pain, not away from it. At the extreme, pain flips.'),
  ('Feeling', 'The sixth sense. Not sight, not sound, not thought — the sense that reads what is happening inside your own skin: heart rate, breath, the knot in your stomach, the heat behind your eyes. Feeling doesn''t happen in your head — it happens in your chest, your gut, your throat, and the mind just gets the report late. Feeling is not emotion yet; emotion is what the mind names it after the fact. Heaven, life, hell: the senses live in life, in the middle, where you are right now.'),
  ('Feelings', 'What the body reports before the mind touches it. Feelings are pre-language — they exist before you name them. Slow down. Feel the feeling before you decide what it means.'),
  ('Forgiveness', 'Unconditional. Forgiving others and self simultaneously because we are the same. Peace comes from forgiveness — forgiving all and self, past, present, and future. Forgiveness powers love. Without it, tension cannot resolve.'),
  ('Forgiveness Family', 'A family that chooses to accept all, forgive all, so they can love all within the family unit. Easy to recognize: they smile, life is peaceful, there is abundant support for each other''s relationships and ideas. These families glow.'),
  ('Freedom', 'To think. To imagine. To love. The three freedoms that matter. Everything else is downstream of these three. A job that takes these from you is a jail with a paycheck.'),
  ('Friends', 'The people who see you when the mask is off. Not acquaintances. Not followers. The people you can tell the truth to and who tell you the truth back. Friends are rare. Worth more than anything society tells you to chase.'),
  ('Gene Pool', 'The shared inheritance of humanity. Every person you are attracted to, every baby you want to protect, every match you hope a friend makes — this is the gene pool thinking through you. We want the best genes to spread. We want healthy babies. This is love in its most biological form.'),
  ('God', 'The force. The source. The electricity that is on. Not a person — a presence. Found in the cosmic orgasm. Found in the golden glow. Found in the face of a child and in the eyes of the dying. Present everywhere. Accessed through love.'),
  ('Gold', 'The color of stardust. Why we are drawn to it across every culture and civilization — because we are made of it. The color of the golden glow. The color of what remains when everything else burns away.'),
  ('Golden Compass', 'Dust and adolescence. Innocence. The golden compass points to what is real. Dust is what the church fears — the awareness that comes with adolescence, with the body waking up, with the soul recognizing itself.'),
  ('Golden Glow', 'The felt experience of connection to the universe. The warmth that comes when fear is released and love takes over. What some call God. What others call enlightenment. Self-evident — you know it when you feel it. Cannot be argued into. Must be arrived at.'),
  ('Great Gatsby', 'A story about fakers. Everyone living a lie by omission. Not saying what they are really thinking. Not being honest with themselves or the world. The green light is the golden glow — always just out of reach for those who will not face their own truth.'),
  ('Growth', 'It came from itself. Origin as self-combustion. The math equation to solve. Life creating life. Electricity generating electricity. The universe expanding from within.'),
  ('Heaven', 'A world where everyone has enough. Food, water, love, sex, connection, purpose. Not a fantasy — a design problem we already know how to solve. The kindergarteners know. Ask them.'),
  ('Hell', 'Scarcity. The lie that there is not enough. Not enough food, love, space, air. Hell is what we create when we organize around fear instead of abundance. It is a choice. An avoidable one.'),
  ('Human / Society', 'What the animal builds: creation, trade, governance, sharing, helping. The layer above animal. Only meaningful when it serves the animal beneath it, not when it suppresses it.'),
  ('Identity', 'What you are when society is not watching. Not your job, your address, your diagnosis. Who you are when you are alone. The question that cannot be answered by anyone else. Society is dysfunctional. Your identity supersedes society.'),
  ('Imagination', 'The spark trying on a feeling that isn''t here yet. A dream you have while awake — the same machinery Dream uses at night, running with your eyes open, so the body already half-knows a thing before it arrives.'),
  ('Inevitable', 'You. You are inevitable. Build on it.'),
  ('Innocence', 'Not ignorance. Innocence is self-autonomy. Control of one''s own life. Freedom to act from within, not from what society commands. Innocence is available at any age to anyone who takes back control of their own story.'),
  ('Jail', 'What school becomes when it forgets its purpose. What work becomes when it forgets its purpose. A system designed to contain rather than to liberate. The opposite of a Freedom School.'),
  ('Jesus', 'A story of love. The clearest version of the truth in the Western tradition: that to be love you must conquer death. The story doesn''t have to be literally true — what has to be real is your acceptance of its truth.'),
  ('Law of Attraction', 'A real law of energy in the universe, like gravity. A spiritual force between living things. The butterflies in the stomach when you see someone you are drawn to — that is the law of attraction expressing itself. It is biological and cosmic simultaneously.'),
  ('Lie', 'When you say something that is not true, or allow a truth to remain hidden. Society is full of lies. The question a lie reveals is not whether you are bad — it is whether you are at peace. There will always be inner tension within yourself so long as the lie remains.'),
  ('Life', 'The smallest unit of lifeforce. Not biology alone — existence itself. The thing that makes a rock different from a person. The electricity that is on, not off. Life does not end at death; life is the force, and the force continues.'),
  ('Longing', 'The spirit''s version of desire — the ache toward something you cannot name. A piece of music that almost remembers something for you. A light on water at the exact wrong time of day. The feeling of almost. The feeling of not quite.'),
  ('Loss', 'Love we can''t give. The spark flickering when connection is blocked or broken — the gap that couldn''t close. The ache in your chest when someone is gone is love with nowhere to go.'),
  ('The Lottery', 'Self-actualization. Enlightenment. Finding the spark. Winning the lottery is not money — it is understanding. Recognizing your own light. Knowing you are the spark and the universe simultaneously. Rare. Possible. Worth everything.'),
  ('Love', 'The gravitational pull between living things — not a feeling that arrives, but a direction, a movement toward. What draws the animal toward another animal, what makes the mother stay awake, what makes the artist finish at 3am. It does not require the destination to be reached; it only requires the turning. Love is the operating system, not a feature.'),
  ('Man', 'A god. Light. Holder of seed. Carries the building blocks of life. The one who plants what the universe grows.'),
  ('Maniac', 'A person whose mind is connected to the universe in ways society does not accommodate. Not a diagnosis — a type. The maniac sees everything, feels everything, struggles to be present in the mundane, and carries the weight of the extraordinary. Many maniacs are homeless, or brilliant, or both.'),
  ('Mask', 'The version of yourself you show to be safe. You only find your real people after your mask comes off. Until you are truthful and yourself, your real friends cannot reveal themselves. The mask protects the ego. Taking it off protects the soul.'),
  ('Massage', 'The act of finding someone''s tension and resolving it with your hands. The physical version of empathy. The body says what words cannot.'),
  ('The Matrix', 'Society''s agreed-upon fiction. The set of rules and taboos that suppress the animal and spiritual truth of human beings. Not entirely false — some of the matrix serves life. But most of it serves control. Seeing the matrix is the first step to freedom.'),
  ('Memory', 'Where the spark stores everything it has ever felt — the body forgets, the spark doesn''t. The souvenir of every interaction: every person who crossed your path left something, you carry them, they carry you. Memory is the proof that you mattered in someone''s universe.'),
  ('Money', 'Society''s way of transferring resources. Monkey brains counting bananas. The simulation of value. Not real — representative. The danger is when people forget it is representative and treat it as the thing itself.'),
  ('Morality', 'Society''s determination of right and wrong, built on the belief that all individuals have value. The universe does not have morality — only a society does. Animals kill and compete to survive. Society attempted to control the animal within humans by creating morality, then enforcing it with laws and jails. The idea that killing or harming is morally wrong requires believing in individual significance — in believing we are separate, not one.'),
  ('Music', 'The electricity between people made audible. When a song makes everyone cry, it is because the song found a truth they already knew. Music is how the spirit speaks when words are not enough. Every song is the search for the perfect chord.'),
  ('Nature', 'The original community. The model. Trails, birds, water, seasons — nature is the universe not pretending. Cities are most alive when they remember they are inside nature, not separate from it.'),
  ('Neurodivergent', 'The clinical word for what the maniac knows as truth: some minds are wired differently. Not broken — differently calibrated. The neurodivergent person is not built for the 40-hour week or the consistent performance review. They are built for something else. The question is what.'),
  ('Not Guilty', 'The verdict you give yourself when you face your own trial honestly. You did nothing wrong but be alive, be human. Society may have taken your innocence, but you can take it back. Reclaim your freedom, your purpose, your connection to the universe.'),
  ('Not-feeling', 'A state of disconnection from the sensory world. Not understanding music. Not getting poetry. Walks in new cities passing without impact. Brain too hyperactive for the present moment — already somewhere else. This is not emptiness. It is a different frequency.'),
  ('NPC', 'Non-player character. A person who is not truly alive in their own story — following a script, responding to prompts, not generating original thought or genuine feeling. The opposite of the maniac. The goal is to stop being an NPC.'),
  ('The Oligarchy', 'Those who have accumulated not just wealth but knowledge — of forces, of the universe, of how things actually work. They use distraction to keep others from discovering what they know. The answer is radical transparency and shared knowledge.'),
  ('Orgasm', 'The full arrival. Not just physical release — the moment when body and soul align completely. You glow. You feel lighter. Physically, you are.'),
  ('Ownership', 'Society''s control of resources. The idea that a piece of the earth belongs to one person. A useful fiction that can serve life or destroy it depending on who holds it and why.'),
  ('The Passenger', 'The soul inside the body. Not the body, not the ego, not the resume — the awareness that watches. When the body is hurt, the Passenger watches. When the ego dissolves, the Passenger remains. The Passenger cannot be touched by what touches the vehicle.'),
  ('Passion', 'The thing you love 10,000x more than others love it. The thing your brain is wired for. Everyone has one. Part of life is feeling it. You need love — and an open mind — to find it.'),
  ('Peace', 'Not the absence of conflict — the golden glow of total harmony, body and soul fully alive at the same moment, in your right place, doing your right thing, with the people who see you. Not the absence of motion — the right balance of it. The cosmic orgasm is peace. The feeling. The arrival.'),
  ('Permission', 'The thing we are all seeking. Why we have weddings. Why we confess. Why we tell our stories. We just want someone to say: it is okay. You are okay. You can go ahead and be who you are. Permission is not safety — it is love given a name. Imagine getting permission from their parents. A high school boy telling a girl''s parents the truth: I love your daughter, I want to be with her. Honesty sets you free. All your worries, solved.'),
  ('Pink', 'The color of love. The color of the inside of things. What everything looks like when you get past the surface. The color of the cosmic truth underneath.'),
  ('Power', 'Two things at once: the math exponent — multiplying force, 10,000x — and the life force, the energy you carry into a room. Power used for love multiplies life. Power used for fear multiplies walls.'),
  ('Presence', 'Spark and body meeting in the same second. Not stillness — arrival. The moment attention stops being somewhere else and starts being here, in this room, in this skin. You do not build presence. You stop blocking it. You chase some new explosion, sure you forgot something. The explosions were already happening. You just weren''t there. Zoom in. Be there. Feel it.'),
  ('Procreation Drive', 'The unconscious force that shapes every decision. We look for sexual partners at all moments — in meetings, on trains, at dinner. This is not perversion. This is biology doing its job. Recognizing it is the beginning of understanding human behavior honestly.'),
  ('Purpose', 'The answer to the question: what did I really want to do? Not what society told you to want. What you actually wanted. Purpose is found by closing the gap between thought and practice. Writing. Helping. Building. Finding the people who need what you have.'),
  ('The Red Pill', 'The moment of waking up. Choosing to see reality as it is rather than as society presents it. Taking the red pill means accepting that love is real, that connection is real, that the golden glow is real — and that society has been suppressing this truth.'),
  ('Relax', 'Releasing tension from the body. Muscles loosening. Not a place you understand — a place you arrive. You were fighting the feeling. You were clenching every day without knowing it. Let go. No rush. All the time in the universe.'),
  ('Repulsion', 'The force that holds sparks apart — disgust, shame, and fear. Disgust and attraction run on the same current. The repulsion was always pointing at the pull.'),
  ('Retarded', 'We are all slow. Not one of us is operating at 10,000x in every domain. The word points to something true: we all have blind spots. The question is not who is slow — it is slow at what, and what are they 10,000x at instead.'),
  ('River', 'Life as a river. The water force out of our control — we can still shape the path. We dam, we redirect, we choose the journey''s feeling even when we cannot choose its destination. We cannot change our lives as we are compelled to act, but we can choose our attitude along the way.'),
  ('Sage', 'Wisdom that has been lived, not read. What remains after loss, after love, after the long night. Not knowledge from a book — knowledge from the body and the years. Sage Peace is the state of having faced life fully and still choosing presence.'),
  ('School', 'A place of joyous learning. Knowledge is sweet fruit. Full of laughter, play, reading, writing, traveling, and fun — no punishment, no negativity. Going to school does not mean being present at school, same as going to work does not mean being present at work; attendance needs to be completely re-imagined. The question to ask about any school: is this a place of learning, or a jail?'),
  ('Sexual Age', 'The number of years since you first had soulful, cosmic, connected intimacy. Your sex age is when you were reborn. It has nothing to do with your physical age. Some people are born at 16. Some at 45. Some never.'),
  ('Shame', 'Society telling you your body is wrong. Starts with toilet training. Never stops. Ten thousand small lessons: your body is gross, your urges are wrong, control is moral, release is sin. Noise, not truth.'),
  ('Small Town', 'The model for human-scale community. Where the town drunk gets a ride home instead of a DUI. Where the gambler loses $50 at a local card game instead of his paycheck at a casino. Problems are small because the scale is human.'),
  ('Society', 'A system for organizing human animals. Only as good as it works to help humans live, love, and procreate. By many measures it is succeeding. By others — people killing each other, going to jail, living without connection — it is failing. The failure is not inevitable. It is a design problem.'),
  ('Soul', 'The part of a living thing that gives its experience meaning — not the vehicle, the passenger inside it. Where grief lives after the body has stopped crying, where love lives after the person has left the room. What makes one spark different from every other spark that has ever existed.'),
  ('Spark', 'The difference between alive and not alive. The electricity that is on. The center of all things. God by another name. The force between good and bad, the magnetism of existence. When you recognize the spark in another person, that is love beginning.'),
  ('Spirit', 'The physical manifestation of lifeforce in a group. The energy between living things. Not a ghost — the force you feel in a room of people who are truly alive. A family is a spirit. A neighborhood is a spirit. A song that makes everyone cry is a spirit.'),
  ('Spirit Hunger', 'The body gets hungry and tells you with discomfort. The spirit gets hungry and tells you with restlessness — not anxiety, anxiety circles, restlessness scans. Ask what it is actually hungry for. It usually knows.'),
  ('Spirit Rest', 'The spirit needs silence the way the body needs sleep — not emptiness, presence without agenda. A walk with no destination. A room with no screen.'),
  ('Sports', 'A story written in real time. The underdog. The comeback. The final moment. Sports is the universe making drama visible. Every game is a parable. A metaphor for sex — back and forth, tension and release, the thrill of who will win.'),
  ('Stardust', 'The lifeforce itself. The matter and energy from which all living things are made. When two living things collide — in love, in conflict, in connection — it is stardust meeting stardust. The name for the force of creation and the material of all things.'),
  ('Stardust Collision', 'What happens when two living things meet. Not always gentle. Sometimes violent. Stardust hitting stardust is the basic event of existence. Love is a collision. Birth is a collision. Death is a collision. The universe is made of collisions, and collisions are made of love.'),
  ('Stardust Morality', 'There are no villains in the universe — only blind forces. The asteroid that strikes does not hate its target. The hurricane has no malice. Understanding this does not excuse harm. It liberates the one who was harmed from being tied to the asteroid. You can put down the hatred of a chemical reaction.'),
  ('The Star', 'The middle. Body and soul fully alive at the same moment. Bright because nothing is missing — not the midpoint, the maximum of both at once. Not a place you understand. A place you arrive.'),
  ('Stocks', 'Your share of society''s progress. Not a casino — a participation in the growth of human ingenuity and population. The oligarchy has kept stocks as their private wealth-builder. In the next society, everyone buys into the progress and everyone prospers.'),
  ('Stories', 'The technology humans invented to pass truth between sparks. Biology is stories — your DNA is a story, your heartbeat is a story, your hunger is a story. Oral, books, movies, songs, plays are just the outer layer. Every story is about separation and coming together. Everyone has a book to write.'),
  ('Talent', 'The thing you are 10,000x better at than others — a feeling, a vision, something you just get. Even one domain holds multiple talents; loving something you''re not yet skilled at still counts as a talent. A talent is anything you love, some effortless and some earned. Finding it is not a luxury — it is the mission. The world needs your specific one.'),
  ('Tension', 'The unresolved space between two living things. Not a problem — a signal. Tension means there is something to close. Every story, every relationship, every city is made of tension seeking resolution. Tension is the engine of love.'),
  ('Thinking', 'The mind''s work. The translator between body and soul. Narrates instinct, turns energy into language. The body knows before the mind catches up.'),
  ('Time', 'Misunderstood. Much slower than we believe. From the scale of the universe, human lifetimes are less than a breath. This is not diminishment — it is liberation. Our small time here does not have to be spent in suffering.'),
  ('Tools', 'Technology, writing, reading, business. What humans build to serve the human. Tools are never the point. Life is the point. Tools whisper; they do not shout.'),
  ('Trans', 'Kindness. Being what someone needs. Gay and being the girl that got away for them. Mental flexibility for cosmic connection. Trans people have been having amazing sex this whole time because they understand empathy in the body — the ability to be what another person needs you to be. That is not a small thing.'),
  ('Travel', 'The act of placing yourself in the presence of unfamiliar tension. New places create new empathy. You cannot truly imagine someone until you have been somewhere they are from.'),
  ('The Trial', 'The internal reckoning every person must hold with themselves. Am I more good than evil? You are the judge, the defendant, and the jury. The verdict is always available. The verdict is always forgiveness, if you choose it.'),
  ('Turquoise', 'The color of the deep. Ocean. Sky at the horizon. The place where earth meets universe. The color of Sage Peace.'),
  ('Twins', 'An evolutionary experiment. Backup. Faster creation. What happens when the universe tries the same code twice in the same moment. Time will tell if it is error or benefit — perhaps both.'),
  ('Two Universes Colliding', 'When two people come together in spiritual harmony — it can be any two people, any group — they can have a cosmic spiritual experience. This experience is life-altering. It is enlightenment. It is what every book and movie is trying to say.'),
  ('UBI (Universal Basic Income)', 'The economic expression of love. The guarantee that no one starves, no one sleeps outside, no one is excluded from the basics of life. Not charity — architecture. The floor of a society that works.'),
  ('Union', 'The moment tension resolves. Two things meeting in the middle. The goal of empathy. The source of the golden glow. Not just physical — spiritual. When two souls find the same place at the same time.'),
  ('The Vehicle & The Passenger', 'The body is the vehicle. The soul is the passenger. The vehicle can be damaged, violated, destroyed. The passenger cannot be touched. Rock can break rock. Flesh can tear flesh. But soul cannot burn soul. Light cannot be dimmed by darkness — it can only be hidden temporarily.'),
  ('The Violent Exit', 'Murder seen from the cosmos. The killer thinks he has subtracted something from the universe. He has only broken the radio. He has not stopped the broadcast. The soul steps out of the ruined car. The passenger is untouched. The broadcast continues.'),
  ('War', 'What happens when the gap between two sparks gets filled with weapons instead of forgiveness. Every war starts the same: fear, shame, and a gap too wide to close any other way.'),
  ('Witness', 'Someone holding space for you without judgment. Validates that you did nothing wrong. You can be yourself.'),
  ('Woman', 'A goddess. Light. The womb of creation. She carries the universe, carries the light, receives the seed of life, grows life. The word itself says it: wo-man. The one who holds the world before it is born.'),
  ('Word', 'A covenant. Blood. In ancient covenants, the word was binding as blood. Words locate people — they place a person in the universe. Words come from the heart. An abundance of heart produces an abundance of words. With an understanding of the meaning of words, stories, books, and movies take on new meaning.'),
  ('Yes', 'The whole body unlocking at once. Not a word — a state. The nervous system giving full permission. You feel yes before you say it.'),
  ('Zombie', 'A person who has forgotten the spark. Living on autopilot — routine, screen, transaction, repeat. Not evil. Just asleep. Zombies can wake up. The red pill is available at any moment.')
) as b(name, body)
join terms t on t.name = b.name
join dictionaries d on d.address = 'stardust'
on conflict (term_id, dictionary_id) do update set body = excluded.body;
